cards.solution:
public class Main {
    public static void main(String[] args) {
        int angka = -5;
        if (angka > 0) {
            System.out.println("Positif");
        } else if (angka < 0) {
            System.out.println("Negatif");
        } else {
            System.out.println("Nol");
        }
    }
}

